/* Styles for the blog notification type */
&.in-app-notification-blog {
  --title-text: light-dark(var(--color-blue-60), #eeeef0);
  --button-background: linear-gradient(var(--color-blue-60), #175fb6);
  --stroke-dark: #32aeff;
  --stroke: light-dark(#19518f, var(--stroke-dark));
  --button-stroke: var(--stroke);
  --button-background-hover: var(--button-background);
  --button-background-active: var(--stroke);
  --button-focus-ring: var(--stroke);
  --button-text: var(--active-background-color);
  --content-border: var(--color-primary-default);
  --icon-url: url("chrome://messenger/skin/icons/sm/circle-question.svg");
  --icon-fill: light-dark(#c4ddf6, #263a47);
  --icon-stroke: var(--color-primary-default);
  --content-background: linear-gradient(#f0f8ff, #f7f7f7);

  @media (prefers-color-scheme: dark) {
    --button-background: linear-gradient(#58c9ff, #32aeff);
  }

  @media (prefers-contrast: more) {
    --content-border: var(--stroke-dark);
    --icon-stroke: var(--stroke-dark);
    --icon-fill: transparent;
  }
